-- Refuse an existing application's public tables; this is a fresh-project-only candidate.
DO $$ BEGIN IF EXISTS(SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relkind IN('r','p')) THEN RAISE EXCEPTION 'Fresh empty application schema required';END IF;END $$;
revoke create on schema public from public,anon,authenticated;
-- ISOLATED CANDIDATE. Supabase auth/roles are platform prerequisites, not created here.
create schema tracking_private;
revoke all on schema tracking_private from public,anon,authenticated;
grant usage on schema tracking_private to service_role;
create table public.projects(id uuid primary key,slug text unique not null,name text not null,is_public boolean not null default false,default_vehicle_id text);
create table public.vehicles(external_id text primary key,project_id uuid not null references public.projects(id),name text not null);
create table public.map_versions(id bigint generated by default as identity primary key,project_id uuid not null references public.projects(id),status text not null check(status in('draft','published')),map_data jsonb not null check(jsonb_typeof(map_data->'features')='array'),created_by uuid references auth.users(id),created_at timestamptz not null default now(),published_at timestamptz);
create index map_latest on public.map_versions(project_id,published_at desc) where status='published';
create table tracking_private.project_admins(project_id uuid references public.projects(id),user_id uuid references auth.users(id),primary key(project_id,user_id));
create table tracking_private.bindings(vehicle_id text primary key references public.vehicles(external_id),tracker_uid text not null unique,credential_env text not null check(credential_env~'^SCORPION_TOKEN_[A-Z0-9_]+$'),active boolean not null default false);
create table tracking_private.runtime(vehicle_id text primary key references public.vehicles(external_id),source_run uuid not null default gen_random_uuid(),revision bigint not null default 0,lease uuid,lease_until timestamptz,latest jsonb,planner_state jsonb,continuity text not null default 'unknown' check(continuity in('known','unknown')),check(pg_column_size(latest)<4096),check(pg_column_size(planner_state)<32768));
create table public.tracking_live_snapshots(vehicle_id text primary key references public.vehicles(external_id),project_id uuid not null references public.projects(id),snapshot jsonb not null,revision bigint not null,updated_at timestamptz not null default clock_timestamp(),check(pg_column_size(snapshot)<32768));
create function public.is_tracking_admin(p uuid) returns boolean language sql stable security definer set search_path=pg_catalog,tracking_private as $$ select exists(select 1 from tracking_private.project_admins where project_id=p and user_id=auth.uid()) $$;
revoke all on function public.is_tracking_admin(uuid) from public;
grant execute on function public.is_tracking_admin(uuid) to anon,authenticated,service_role;
alter table public.projects enable row level security;
alter table public.vehicles enable row level security;
alter table public.map_versions enable row level security;
alter table public.tracking_live_snapshots enable row level security;
alter table tracking_private.project_admins enable row level security;
alter table tracking_private.bindings enable row level security;
alter table tracking_private.runtime enable row level security;
create policy project_read on public.projects for select to anon,authenticated using(is_public or public.is_tracking_admin(id));
create policy vehicle_read on public.vehicles for select to anon,authenticated using(exists(select 1 from public.projects p where p.id=project_id));
create policy map_read on public.map_versions for select to anon,authenticated using(public.is_tracking_admin(project_id) or(status='published' and exists(select 1 from public.projects p where p.id=project_id and p.is_public)));
create policy map_insert on public.map_versions for insert to authenticated with check(public.is_tracking_admin(project_id) and created_by=auth.uid());
create policy snapshot_read on public.tracking_live_snapshots for select to anon,authenticated using(exists(select 1 from public.projects p where p.id=project_id));
revoke all on all tables in schema public from public,anon,authenticated;
grant select on public.projects,public.vehicles,public.map_versions,public.tracking_live_snapshots to anon,authenticated;
grant insert on public.map_versions to authenticated;
grant usage,select on sequence public.map_versions_id_seq to authenticated;
grant all on all tables in schema public to service_role;
grant usage,select on all sequences in schema public to service_role;
grant all on all tables in schema tracking_private to service_role;
create function public.selected_tracking_snapshot(target_vehicle text) returns jsonb language sql stable security invoker set search_path=pg_catalog,public as $$ select snapshot from public.tracking_live_snapshots where vehicle_id=target_vehicle $$;
revoke all on function public.selected_tracking_snapshot(text) from public;
grant execute on function public.selected_tracking_snapshot(text) to anon,authenticated,service_role;
-- Lease/fence is necessary shared state: Edge globals are not authoritative.
create function tracking_private.publish_current(target_vehicle text) returns void language plpgsql security definer set search_path=pg_catalog,public,tracking_private as $$
declare r tracking_private.runtime;v public.vehicles;g jsonb;s jsonb;op jsonb;c text;snap jsonb;
begin
 select * into r from tracking_private.runtime where vehicle_id=target_vehicle;
 if not found or r.latest is null then return;end if;
 select * into v from public.vehicles where external_id=target_vehicle;
 g:=r.latest;s:=r.planner_state;op:=s->'operational_state';c:=r.continuity;
 snap:=jsonb_build_object('selection','scorpion','position',jsonb_build_object('vehicle_id',target_vehicle,'project_id',v.project_id,'latitude',g->'latitude','longitude',g->'longitude','speed_kmh',g->'speed_kmh','bearing_deg',g->'heading','accuracy_m',g->'accuracy_m','source_recorded_at',g->'source_recorded_at','received_at',g->'received_at','source','scorpiontrack','source_run_id',r.source_run,'ui_observation_valid',true,'movement_state',op->'movement'),'stop',case when c='known' then s-'last_gps_history_id' else null end,'eta',null);
 -- Public duplicate speed samples are unnecessary; retain them only in private planner state.
 if c='known' then snap:=snap #- '{stop,operational_state,samples}';end if;
 insert into public.tracking_live_snapshots(vehicle_id,project_id,snapshot,revision) values(target_vehicle,v.project_id,snap,r.revision)
 on conflict(vehicle_id) do update set snapshot=excluded.snapshot,revision=excluded.revision,updated_at=clock_timestamp();
end $$;
revoke all on function tracking_private.publish_current(text) from public,anon,authenticated;
create function public.tracking_claim(target_vehicle text) returns jsonb language plpgsql security definer set search_path=pg_catalog,public,tracking_private as $$
declare r tracking_private.runtime; v public.vehicles; b tracking_private.bindings; m public.map_versions; t uuid;
begin
 select * into v from public.vehicles where external_id=target_vehicle;
 if not found then return null;end if;
 select * into b from tracking_private.bindings where vehicle_id=target_vehicle and active;
 if not found then return null;end if;
 select * into m from public.map_versions where project_id=v.project_id and status='published' order by published_at desc nulls last,id desc limit 1;
 if not found then return null;end if;
 insert into tracking_private.runtime(vehicle_id) values(target_vehicle) on conflict do nothing;
 select * into r from tracking_private.runtime where vehicle_id=target_vehicle for update;
 if r.lease_until>clock_timestamp() then return null;end if;
 if r.latest is not null and not exists(select 1 from public.tracking_live_snapshots where vehicle_id=target_vehicle) then perform tracking_private.publish_current(target_vehicle);end if;
 t:=gen_random_uuid();
 update tracking_private.runtime set lease=t,lease_until=clock_timestamp()+interval '4500 milliseconds' where vehicle_id=target_vehicle;
 return jsonb_build_object('vehicle',v,'binding',jsonb_build_object('tracker_uid',b.tracker_uid,'credential_env',b.credential_env),'mapVersion',jsonb_build_object('id',m.id,'map_data',m.map_data),'runtime',to_jsonb(r),'lease',t);
end $$;
revoke all on function public.tracking_claim(text) from public,anon,authenticated;
grant execute on function public.tracking_claim(text) to service_role;
create function public.tracking_commit(target_vehicle text,expected_revision bigint,lease_token uuid,map_version bigint,payload jsonb) returns text language plpgsql security definer set search_path=pg_catalog,public,tracking_private as $$
declare r tracking_private.runtime; v public.vehicles; g jsonb; s jsonb; op jsonb; snap jsonb; p_at timestamptz; mv bigint; c text;
begin
 select * into r from tracking_private.runtime where vehicle_id=target_vehicle for update;
 if not found or r.revision<>expected_revision or r.lease is distinct from lease_token or r.lease_until is null or r.lease_until<clock_timestamp() then return 'fenced';end if;
 select * into v from public.vehicles where external_id=target_vehicle;
 select id into mv from public.map_versions where project_id=v.project_id and status='published' order by published_at desc nulls last,id desc limit 1;
 if mv is distinct from map_version then return 'map_changed';end if;
 g:=payload->'gps';s:=payload->'state';op:=s->'operational_state';c:=payload->>'continuity';
 if (g->>'vehicle_id') is distinct from target_vehicle or (g->>'project_id') is distinct from v.project_id::text or (s->>'vehicle_id') is distinct from target_vehicle or (s->>'project_id') is distinct from v.project_id::text then raise exception 'Context identity mismatch';end if;
 if g is null or s is null or op is null or c is null or g->>'id' is null or op->>'mapVersion' is null or g->>'source_recorded_at' is null or g->>'latitude' is null or g->>'longitude' is null or g->>'speed_kmh' is null or jsonb_typeof(op->'samples') is distinct from 'array' or jsonb_typeof(op->'completedStops') is distinct from 'array' then raise exception 'Missing bounded envelope fields';end if;
 if g-array['id','vehicle_id','project_id','tracking_source_run_id','received_at','source_recorded_at','latitude','longitude','speed_kmh','heading','accuracy_m']<>'{}'::jsonb then raise exception 'Unexpected observation attributes';end if;
 if pg_column_size(payload)>48000 or c not in('known','unknown') or (g->>'tracking_source_run_id') is distinct from r.source_run::text or (g->>'id')::bigint<>r.revision+1 or (op->>'mapVersion')::bigint<>map_version or (op->>'sourceRun') is distinct from r.source_run::text or (op->>'timestamp') is distinct from (g->>'source_recorded_at') or jsonb_array_length(op->'samples')>24 or jsonb_array_length(op->'completedStops')>5 then raise exception 'Invalid bounded operational envelope';end if;
 p_at:=(g->>'source_recorded_at')::timestamptz;
 if p_at>clock_timestamp()+interval '60 seconds' or p_at<clock_timestamp()-interval '24 hours' or r.latest is not null and p_at<=(r.latest->>'source_recorded_at')::timestamptz then return 'duplicate_or_invalid_time';end if;
 if not ((g->>'latitude')::double precision between -90 and 90 and (g->>'longitude')::double precision between -180 and 180 and (g->>'speed_kmh')::double precision between 0 and 250) then raise exception 'Invalid fix';end if;
 -- Only one private current fix and planner envelope. No append-only GPS/receipt/event table.
 update tracking_private.runtime set latest=g,planner_state=s,continuity=c,revision=revision+1 where vehicle_id=target_vehicle;
 perform tracking_private.publish_current(target_vehicle);
 return 'committed';
end $$;
revoke all on function public.tracking_commit(text,bigint,uuid,bigint,jsonb) from public,anon,authenticated;
grant execute on function public.tracking_commit(text,bigint,uuid,bigint,jsonb) to service_role;
-- Realtime activation is deliberately separate; no cron, outbound call or publication here.

-- Explicit binding changes invalidate old in-flight owners and old journey context.
create function tracking_private.binding_changed() returns trigger language plpgsql security definer set search_path=pg_catalog,public,tracking_private as $$
declare n bigint;
begin
 if new.tracker_uid is distinct from old.tracker_uid or new.credential_env is distinct from old.credential_env or new.active is distinct from old.active then
 update tracking_private.runtime set source_run=gen_random_uuid(),revision=revision+1,lease=null,lease_until=null,latest=null,planner_state=null,continuity='unknown' where vehicle_id=new.vehicle_id returning revision into n;
 update public.tracking_live_snapshots set revision=n,snapshot=jsonb_build_object('selection','scorpion','position',null,'stop',null,'eta',null),updated_at=clock_timestamp() where vehicle_id=new.vehicle_id;
 end if;return new;
end $$;
revoke all on function tracking_private.binding_changed() from public,anon,authenticated;
create trigger binding_context_changed after update on tracking_private.bindings for each row execute function tracking_private.binding_changed();
